INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0ca53f78-1895-502a-a119-cc6fd72a52bc', 'Norway enterprises'' transparency and work on fundamental human rights', 'Act relating to enterprises'' transparency and work on fundamental human rights and decent working conditions (Transparency Act)', 'The Act relating to enterprises'' transparency and work on fundamental human rights and decent working conditions (Transparency Act) is a Norwegian law that requires certain large companies to report on their efforts to promote fundamental human rights and decent working conditions throughout their supply chains. The law applies to companies with a turnover exceeding NOK 900 million and more than 250 employees. These companies are required to report on their policies, due diligence processes, and actions taken to address risks related to human rights and working conditions, as well as any measures taken to mitigate those risks. The Transparency Act also requires companies to report on their environmental impact, including greenhouse gas emissions, and measures taken to reduce their environmental footprint. The law emphasizes the importance of stakeholder engagement and requires companies to involve relevant stakeholders, including workers and trade unions, in their reporting process. It also provides for penalties for non-compliance.', 'The Act relating to enterprises'' transparency and work on fundamental human rights and decent working conditions (Transparency Act) is a Norwegian law that requires certain large companies to report on their efforts to promote fundamental human rights and decent working conditions throughout their supply chains. The law applies to companies with a turnover exceeding NOK 900 million and more than 250 employees. These companies are required to report on their policies, due diligence processes, and actions taken to address risks related to human rights and working conditions, as well as any measures taken to mitigate those risks. The Transparency Act also requires companies to report on their environmental impact, including greenhouse gas emissions, and measures taken to reduce their environmental footprint. The law emphasizes the importance of stakeholder engagement and requires companies to involve relevant stakeholders, including workers and trade unions, in their reporting process. It also provides for penalties for non-compliance.', 'The Act relating to enterprises'' transparency and work on fundamental human rights and decent working conditions (Transparency Act) is a Norwegian law that requires certain large companies to report on their efforts to promote fundamental human rights and decent working conditions throughout their supply chains. The law applies to companies with a turnover exceeding NOK 900 million and more than 250 employees. These companies are required to report on their policies, due diligence processes, and actions taken to address risks related to human rights and working conditions, as well as any measures taken to mitigate those risks. The Transparency Act also requires companies to report on their environmental impact, including greenhouse gas emissions, and measures taken to reduce their environmental footprint. The law emphasizes the importance of stakeholder engagement and requires companies to involve relevant stakeholders, including workers and trade unions, in their reporting process. It also provides for penalties for non-compliance.', 'Norway', 'climate', 'in_force', '2021-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_27', ARRAY['sdg8', 'sdg13', 'regulations', 'sdg17', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'norway']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0e2b396a-374d-5a57-961d-254d13eaab0b', 'Norway Business Transparency and Work on Basic Human Rights', 'Act on Business Transparency and Work on Basic Human Rights and Decent Working Conditions (Transparency Act)', 'The purpose of the proposed Transparency Act is to promote corporate respect for the basics human rights and decent working conditions in connection with the production of goods and services, and to ensure public access to information on how companies deal with negative impacts on basic human rights and decent working conditions.', 'The purpose of the proposed Transparency Act is to promote corporate respect for the basics human rights and decent working conditions in connection with the production of goods and services, and to ensure public access to information on how companies deal with negative impacts on basic human rights and decent working conditions.', 'The purpose of the proposed Transparency Act is to promote corporate respect for the basics human rights and decent working conditions in connection with the production of goods and services, and to ensure public access to information on how companies deal with negative impacts on basic human rights and decent working conditions.', 'Norway', 'social', 'in_force', '2020-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_18', ARRAY['sdg8', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'norway']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b188e78c-2b66-5199-9505-9b8e864d2ceb', 'Norway Guidelines ESG reporting in the shipping and offshore', 'Guidelines ESG reporting in the shipping and offshore industries', 'The Guidelines for ESG Reporting in the Shipping and Offshore Industries 2020 Norway aim to provide a standardized framework for companies in the industry to report on their Environmental, Social, and Governance (ESG) performance. The guidelines cover various aspects of ESG reporting, including emissions, waste, and social responsibility. The guidelines emphasize the importance of transparency and consistency in reporting, with a focus on providing stakeholders with relevant and reliable information. Companies are encouraged to report on both quantitative and qualitative data, and to use internationally recognized standards and frameworks wherever possible. In addition, the guidelines provide specific recommendations for reporting on issues such as gender diversity, human rights, and anti-corruption measures. Companies are also encouraged to engage with stakeholders and seek feedback on their ESG performance.', 'The Guidelines for ESG Reporting in the Shipping and Offshore Industries 2020 Norway aim to provide a standardized framework for companies in the industry to report on their Environmental, Social, and Governance (ESG) performance. The guidelines cover various aspects of ESG reporting, including emissions, waste, and social responsibility. The guidelines emphasize the importance of transparency and consistency in reporting, with a focus on providing stakeholders with relevant and reliable information. Companies are encouraged to report on both quantitative and qualitative data, and to use internationally recognized standards and frameworks wherever possible. In addition, the guidelines provide specific recommendations for reporting on issues such as gender diversity, human rights, and anti-corruption measures. Companies are also encouraged to engage with stakeholders and seek feedback on their ESG performance.', 'The Guidelines for ESG Reporting in the Shipping and Offshore Industries 2020 Norway aim to provide a standardized framework for companies in the industry to report on their Environmental, Social, and Governance (ESG) performance. The guidelines cover various aspects of ESG reporting, including emissions, waste, and social responsibility. The guidelines emphasize the importance of transparency and consistency in reporting, with a focus on providing stakeholders with relevant and reliable information. Companies are encouraged to report on both quantitative and qualitative data, and to use internationally recognized standards and frameworks wherever possible. In addition, the guidelines provide specific recommendations for reporting on issues such as gender diversity, human rights, and anti-corruption measures. Companies are also encouraged to engage with stakeholders and seek feedback on their ESG performance.', 'Norway', 'climate', 'in_force', '2020-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_26', ARRAY['guidance_frameworks', 'sdg13', 'sdg5', 'sdg16', 'norway', 'disclosure', 'sdg12', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('397756c5-7404-545c-b8e8-f9b60898d897', 'Norway Government Pension Fund Global Management Mandate', 'Government Pension Fund Global Management Mandate', 'Outlining legal requirements for the Government Pension Fund Global Management Mandate.', 'Outlining legal requirements for the Government Pension Fund Global Management Mandate.', 'Outlining legal requirements for the Government Pension Fund Global Management Mandate.', 'Norway', 'governance', 'in_force', '2020-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_8', ARRAY['mandatory', 'other sustainability policy', 'mandatory_regulations', 'norway']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('241aa73d-da79-5e5a-99de-4fafa69d5db2', 'Norway Supply Chain Transparency: Proposal for an Act regulating', 'Supply Chain Transparency: Proposal for an Act regulating Enterprises’ transparency about supply chains, duty to know and due diligence', 'Report of the Ethics Information Committee, appointed by the Norwegian government on 1 June 2018, to assess the adoption of an ethics information law. Recommendations delivered to the Ministry of Children and Families on 28 November 2019.', 'Report of the Ethics Information Committee, appointed by the Norwegian government on 1 June 2018, to assess the adoption of an ethics information law. Recommendations delivered to the Ministry of Children and Families on 28 November 2019.', 'Report of the Ethics Information Committee, appointed by the Norwegian government on 1 June 2018, to assess the adoption of an ethics information law. Recommendations delivered to the Ministry of Children and Families on 28 November 2019.', 'Norway', 'climate', 'in_force', '2019-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_17', ARRAY['regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'norway']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2c60fa82-6b1d-546e-9ae1-df2fb1c09921', 'Norway Norwegian Code of Practice for Corporate Governance', 'Norwegian Code of Practice for Corporate Governance', 'The Norwegian Code of Practice for Corporate Governance, revised in 2018, provides guidelines to promote transparency, accountability, and sustainable value creation among listed companies in Norway. The Code emphasizes principles of effective governance, equitable treatment of shareholders, and responsible decision-making by corporate boards. Its recommendations align with international best practices and the EU’s corporate governance directives.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5ef6c470-8e63-5e03-9d9a-4830857214dd', 'Norway Oslo Børs guidance on the reporting of corporate', 'Oslo Børs guidance on the reporting of corporate responsibility', 'This guidance is intended to help simplify companies’ efforts to: 1. Identify and prioritise the opportunities and risks of greatest significance to company results and their most important stakeholders; and to 2. Report efficiently on their management of and performance in areas of risk defined in accordance with their own needs and those of their stakeholders.', 'This guidance is intended to help simplify companies’ efforts to: 1. Identify and prioritise the opportunities and risks of greatest significance to company results and their most important stakeholders; and to 2. Report efficiently on their management of and performance in areas of risk defined in accordance with their own needs and those of their stakeholders.', 'This guidance is intended to help simplify companies’ efforts to: 1. Identify and prioritise the opportunities and risks of greatest significance to company results and their most important stakeholders; and to 2. Report efficiently on their management of and performance in areas of risk defined in accordance with their own needs and those of their stakeholders.', 'Norway', 'climate', 'in_force', '2018-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_11', ARRAY['guidance_frameworks', 'mandatory', 'other sustainability policy', 'norway']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('283386e0-fe8a-590d-95b2-20651d08b78d', 'Norway observation and exclusion from the Government Pension Fund', 'Guidelines for the observation and exclusion from the Government Pension Fund Global', 'These guidelines cover investments in the Fund’s equity and fixed-income portfolios, as well as instruments in the Fund’s real-estate portfolio issued by companies listed on a regulated market.', 'These guidelines cover investments in the Fund’s equity and fixed-income portfolios, as well as instruments in the Fund’s real-estate portfolio issued by companies listed on a regulated market.', 'These guidelines cover investments in the Fund’s equity and fixed-income portfolios, as well as instruments in the Fund’s real-estate portfolio issued by companies listed on a regulated market.', 'Norway', 'climate', 'in_force', '2016-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_9', ARRAY['guidance_frameworks', 'voluntary', 'other sustainability policy', 'norway']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('081564c1-b5b2-5f13-ac6f-f8cc220abedc', 'Norway Business and Human Rights National Action Plan', 'Business and Human Rights National Action Plan for the implementation of the UN Guiding Principles', 'The plan begins by describing developments in the field of corporate social responsibility (CSR) and why the Government considers this important. The plan has the same three-part structure as the UN Guiding Principles on Business and Human Rights.', 'The plan begins by describing developments in the field of corporate social responsibility (CSR) and why the Government considers this important. The plan has the same three-part structure as the UN Guiding Principles on Business and Human Rights.', 'The plan begins by describing developments in the field of corporate social responsibility (CSR) and why the Government considers this important. The plan has the same three-part structure as the UN Guiding Principles on Business and Human Rights.', 'Norway', 'climate', 'in_force', '2015-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_5', ARRAY['other sustainability policy', 'regulations', 'sdg16', 'norway', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('263c7612-35e6-5dee-bc4e-2c509df2e41d', 'Norway Norwegian Code of Practice for Corporate Governance', 'The Norwegian Code of Practice for Corporate Governance, 2014', 'The objective of this Code of Practice is that companies listed on regulated markets in Norway will practice corporate governance that regulates the division of roles between shareholders, the board of directors and executive management more comprehensively than is required by legislation.', 'The objective of this Code of Practice is that companies listed on regulated markets in Norway will practice corporate governance that regulates the division of roles between shareholders, the board of directors and executive management more comprehensively than is required by legislation.', 'The objective of this Code of Practice is that companies listed on regulated markets in Norway will practice corporate governance that regulates the division of roles between shareholders, the board of directors and executive management more comprehensively than is required by legislation.', 'Norway', 'governance', 'in_force', '2014-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_1', ARRAY['regulations', 'mandatory', 'sdg16', 'norway', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9802b9e2-abd6-5254-86fa-54512be184d5', 'Norway Securities Trading Act (Securities Trading Act)', 'Securities Trading Act (Securities Trading Act)', 'This document outlines the Norwegian Securities Trading Act.', 'This document outlines the Norwegian Securities Trading Act.', 'This document outlines the Norwegian Securities Trading Act.', 'Norway', 'governance', 'in_force', '2014-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_7', ARRAY['mandatory', 'other sustainability policy', 'norway', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6013a99c-6275-5beb-81c2-c50c19f79678', 'Norway 4 Regulatory amendments and licences in major financial', '4 Regulatory amendments and licences in major financial market matters', 'Sections 4.1.1 to 4.1.6 of this chapter provide an overview of the main financial market regulatory amendments in 2013. Section 4.1.7 provides a brief overview of regulations laid down in 2013. Section 4.2 lists key licences granted that same year, with a brief discussion of each case.', 'Sections 4.1.1 to 4.1.6 of this chapter provide an overview of the main financial market regulatory amendments in 2013. Section 4.1.7 provides a brief overview of regulations laid down in 2013. Section 4.2 lists key licences granted that same year, with a brief discussion of each case.', 'Sections 4.1.1 to 4.1.6 of this chapter provide an overview of the main financial market regulatory amendments in 2013. Section 4.1.7 provides a brief overview of regulations laid down in 2013. Section 4.2 lists key licences granted that same year, with a brief discussion of each case.', 'Norway', 'governance', 'in_force', '2013-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_4', ARRAY['mandatory', 'other sustainability policy', 'norway', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5f6ef5d0-996d-5b14-b956-e0aa9e7ba217', 'Norway Industry recommendation for the members of the Norwegian', 'Industry recommendation for the members of the Norwegian Mutual Funds Association: Exercise of ownership', 'This industry recommendation was last updated on 7 June 2012, where the recommendation for the first time also includes follow- up of ownership rights for customer funds in active (discretionary) management. The update also involves a Norwegian implementation of "Principles for the exercise and ownership rights in investment companies", which is published by the European Fund and Asset Management Association (EFAMA).', 'This industry recommendation was last updated on 7 June 2012, where the recommendation for the first time also includes follow- up of ownership rights for customer funds in active (discretionary) management. The update also involves a Norwegian implementation of "Principles for the exercise and ownership rights in investment companies", which is published by the European Fund and Asset Management Association (EFAMA).', 'This industry recommendation was last updated on 7 June 2012, where the recommendation for the first time also includes follow- up of ownership rights for customer funds in active (discretionary) management. The update also involves a Norwegian implementation of "Principles for the exercise and ownership rights in investment companies", which is published by the European Fund and Asset Management Association (EFAMA).', 'Norway', 'governance', 'in_force', '2012-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_15', ARRAY['guidance_frameworks', 'other sustainability policy', 'norway', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
