INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('355d6ddb-9e42-514b-9eee-57ee11672629', 'Norway Changes to Norwegian Code of Practice for Corporate', 'Changes to Norwegian Code of Practice for Corporate Governance: Autumn 2011', 'Norwegian public limited companies are governed by the Public Companies Act, which is, on important areas (e.g., information requirements, investor protection and accounting), supplemented by other mandatory laws such as the Securities Trading Act, the Stock Exchange Act and the Accounting Act. Companies listed in Oslo are also subject to the continuing obligations of listed companies as adopted by the Oslo Stock Exchange.', 'Norwegian public limited companies are governed by the Public Companies Act, which is, on important areas (e.g., information requirements, investor protection and accounting), supplemented by other mandatory laws such as the Securities Trading Act, the Stock Exchange Act and the Accounting Act. Companies listed in Oslo are also subject to the continuing obligations of listed companies as adopted by the Oslo Stock Exchange.', 'Norwegian public limited companies are governed by the Public Companies Act, which is, on important areas (e.g., information requirements, investor protection and accounting), supplemented by other mandatory laws such as the Securities Trading Act, the Stock Exchange Act and the Accounting Act. Companies listed in Oslo are also subject to the continuing obligations of listed companies as adopted by the Oslo Stock Exchange.', 'Norway', 'climate', 'in_force', '2011-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_14', ARRAY['regulations', 'mandatory', 'sdg16', 'norway', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d776ab7d-5618-59ef-863d-0f9a0601ca41', 'Norway Corporate social responsibility in a global economy', 'Corporate social responsibility in a global economy', 'In its white paper on corporate social responsibility in a global economy, the Government outlines how it intends to address this issue. This document provides a brief overview of the white paper. It intends to provide useful information and stimulate debate.', 'In its white paper on corporate social responsibility in a global economy, the Government outlines how it intends to address this issue. This document provides a brief overview of the white paper. It intends to provide useful information and stimulate debate.', 'In its white paper on corporate social responsibility in a global economy, the Government outlines how it intends to address this issue. This document provides a brief overview of the white paper. It intends to provide useful information and stimulate debate.', 'Norway', 'governance', 'in_force', '2009-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_3', ARRAY['mandatory', 'mandatory_regulations', 'norway', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('84e59050-3213-5c77-b6d0-9bfb79671194', 'Norway Greenhouse Gas Emissions Trading Act', 'The Greenhouse Gas Emissions Trading Act', 'The Act aims to limit emissions of GHGs in a cost-effective manner by means of a system involving the duty to surrender GHG emission allowances and freely transferable emission allowances.', 'The Act aims to limit emissions of GHGs in a cost-effective manner by means of a system involving the duty to surrender GHG emission allowances and freely transferable emission allowances.', 'The Act aims to limit emissions of GHGs in a cost-effective manner by means of a system involving the duty to surrender GHG emission allowances and freely transferable emission allowances.', 'Norway', 'climate', 'in_force', '2004-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_24', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'norway']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d90efb52-5244-5c9e-a3ac-4e403d9dd0f7', 'Norway Public Limited Liability Companies Act (Public Limited Liability', 'Public Limited Liability Companies Act (Public Limited Liability Companies Act)', 'The Public Limited Liability Companies Act contains provisions on, among other things, founding basis and share subscription, company capital, share owners and change of ownership. Furthermore, rules are given about the general meeting, the company''s management, the auditor, distribution of dividends, subscription and acquisition of own shares, increase and decrease of share capital and financial instruments (loans with the right to demand issued shares, subscription rights, independent subscription rights and loans with special conditions). Provisions are also made on the merger and division of companies, conversion to a limited liability company, dissolution and liquidation and compensation.', 'The Public Limited Liability Companies Act contains provisions on, among other things, founding basis and share subscription, company capital, share owners and change of ownership. Furthermore, rules are given about the general meeting, the company''s management, the auditor, distribution of dividends, subscription and acquisition of own shares, increase and decrease of share capital and financial instruments (loans with the right to demand issued shares, subscription rights, independent subscription rights and loans with special conditions). Provisions are also made on the merger and division of companies, conversion to a limited liability company, dissolution and liquidation and compensation.', 'The Public Limited Liability Companies Act contains provisions on, among other things, founding basis and share subscription, company capital, share owners and change of ownership. Furthermore, rules are given about the general meeting, the company''s management, the auditor, distribution of dividends, subscription and acquisition of own shares, increase and decrease of share capital and financial instruments (loans with the right to demand issued shares, subscription rights, independent subscription rights and loans with special conditions). Provisions are also made on the merger and division of companies, conversion to a limited liability company, dissolution and liquidation and compensation.', 'Norway', 'governance', 'in_force', '2003-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_16', ARRAY['mandatory', 'other sustainability policy', 'norway', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c67534e5-6dbe-5cec-967d-bbbef1d82743', 'Norway Accounting Act (Regnskapsloven)', 'Accounting Act (Regnskapsloven)', 'The Norwegian Accounting Act, enacted in 1998, establishes a framework for financial reporting and accounting practices for entities operating in Norway. It mandates the preparation of annual financial statements and management reports that provide a true and fair view of an entity’s financial position and performance. The Act aligns with EU directives and incorporates provisions for sustainability-related disclosures, emphasizing transparency and accountability in corporate reporting.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6a5bd085-4c34-5f4f-a7de-c6235a2e8187', 'Norway Norwegian Public Limited Liability Companies Act', 'Norwegian Public Limited Liability Companies Act', 'This unofficial translation of the Norwegian Public Limited Liability Companies Act is entirely in the ownership.', 'This unofficial translation of the Norwegian Public Limited Liability Companies Act is entirely in the ownership.', 'This unofficial translation of the Norwegian Public Limited Liability Companies Act is entirely in the ownership.', 'Norway', 'governance', 'in_force', '1997-01-01'::date, 'Norway', 'https://www.carrotsandsticks.org/policies/136_6', ARRAY['regulations', 'mandatory', 'norway', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ba3038ca-ab62-5367-9f6d-cebcf5de8232', 'Oman MSX ESG Disclosure Guideline', 'MSX ESG Disclosure Guideline', 'The MSX ESG Disclosure Guideline in Oman aims to assist listed companies in reporting their environmental, social, and governance (ESG) performance. It requires disclosing metrics through a platform, aligns with global sustainability trends, and targets investors, clients, and the community for transparent and responsible business practices.', 'The MSX ESG Disclosure Guideline in Oman aims to assist listed companies in reporting their environmental, social, and governance (ESG) performance. It requires disclosing metrics through a platform, aligns with global sustainability trends, and targets investors, clients, and the community for transparent and responsible business practices.', 'The MSX ESG Disclosure Guideline in Oman aims to assist listed companies in reporting their environmental, social, and governance (ESG) performance. It requires disclosing metrics through a platform, aligns with global sustainability trends, and targets investors, clients, and the community for transparent and responsible business practices.', 'Oman', 'climate', 'in_force', '2023-01-01'::date, 'Oman', 'https://www.carrotsandsticks.org/policies/200_1', ARRAY['guidance_frameworks', 'sdg11', 'sdg16', 'voluntary', 'oman']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f0639e44-62bf-540f-bda1-20fdaa17e5ec', 'Oman Questions and queries raised on the Code', 'Questions and queries raised on the Code of Corporate Governance, 2016', 'Since the issue of the Code of Corporate Governance vide CMA Circular No. (E/4/2015) on 22/7/2015, several questions; queries and comments have been raised outlining the concerns of directors and officers of public listed companies and other parties.', 'Since the issue of the Code of Corporate Governance vide CMA Circular No. (E/4/2015) on 22/7/2015, several questions; queries and comments have been raised outlining the concerns of directors and officers of public listed companies and other parties.', 'Since the issue of the Code of Corporate Governance vide CMA Circular No. (E/4/2015) on 22/7/2015, several questions; queries and comments have been raised outlining the concerns of directors and officers of public listed companies and other parties.', 'Oman', 'governance', 'in_force', '2016-01-01'::date, 'Oman', 'https://www.carrotsandsticks.org/policies/137_1', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'oman']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4e86cbbb-f060-55c4-b6df-62c1d5e29898', 'OECD Guidelines for Multinational Enterprises on Responsible Business Conduct', 'OECD Guidelines for Multinational Enterprises on Responsible Business Conduct', 'The 2023 OECD Guidelines for Multinational Enterprises provide recommendations to promote responsible business conduct in areas such as human rights, labor, environment, anti-corruption, consumer interests, and taxation. Updated to reflect societal, environmental, and technological priorities, the guidelines include stronger due diligence requirements, new recommendations on technology use, and expanded protections for vulnerable groups. The framework emphasizes risk-based due diligence to prevent and address adverse impacts and supports sustainable development goals. It is supported by National Contact Points (NCPs) for Responsible Business Conduct, which act as a mechanism for implementation and mediation. The guidelines are non-binding but represent a significant international standard for aligning corporate practices with sustainability objectives.', 'The 2023 OECD Guidelines for Multinational Enterprises provide recommendations to promote responsible business conduct in areas such as human rights, labor, environment, anti-corruption, consumer interests, and taxation. Updated to reflect societal, environmental, and technological priorities, the guidelines include stronger due diligence requirements, new recommendations on technology use, and expanded protections for vulnerable groups. The framework emphasizes risk-based due diligence to prevent and address adverse impacts and supports sustainable development goals. It is supported by National Contact Points (NCPs) for Responsible Business Conduct, which act as a mechanism for implementation and mediation. The guidelines are non-binding but represent a significant international standard for aligning corporate practices with sustainability objectives.', 'The 2023 OECD Guidelines for Multinational Enterprises provide recommendations to promote responsible business conduct in areas such as human rights, labor, environment, anti-corruption, consumer interests, and taxation. Updated to reflect societal, environmental, and technological priorities, the guidelines include stronger due diligence requirements, new recommendations on technology use, and expanded protections for vulnerable groups. The framework emphasizes risk-based due diligence to prevent and address adverse impacts and supports sustainable development goals. It is supported by National Contact Points (NCPs) for Responsible Business Conduct, which act as a mechanism for implementation and mediation. The guidelines are non-binding but represent a significant international standard for aligning corporate practices with sustainability objectives.', 'OECD', 'climate', 'in_force', '2023-01-01'::date, 'OECD', 'https://www.oecd.org/content/dam/oecd/en/publications/reports/2023/06/oecd-guidelines-for-multinational-enterprises-on-responsible-business-conduct_a0b49990/81f92357-en.pdf', ARRAY['guidance_frameworks', 'sdg2', 'oecd', 'sdg10', 'sdg7', 'sdg16', 'sdg12', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('18edd955-5797-5e0f-8755-c67477612017', 'G20/OECD Principles of Corporate Governance', 'G20/OECD Principles of Corporate Governance, 2023', 'The Principles of Corporate Governance are intended to help policy makers evaluate and improve the legal, regulatory, and institutional framework for corporate governance, with a view to supporting economic efficiency, sustainable growth and financial stability. This is primarily achieved by providing shareholders, board members and executives, the workforce and relevant stakeholders, as well as financial intermediaries and service providers with the right information and incentives to perform their roles and help to ensure accountability within a framework of checks and balances.', 'The Principles of Corporate Governance are intended to help policy makers evaluate and improve the legal, regulatory, and institutional framework for corporate governance, with a view to supporting economic efficiency, sustainable growth and financial stability. This is primarily achieved by providing shareholders, board members and executives, the workforce and relevant stakeholders, as well as financial intermediaries and service providers with the right information and incentives to perform their roles and help to ensure accountability within a framework of checks and balances.', 'The Principles of Corporate Governance are intended to help policy makers evaluate and improve the legal, regulatory, and institutional framework for corporate governance, with a view to supporting economic efficiency, sustainable growth and financial stability. This is primarily achieved by providing shareholders, board members and executives, the workforce and relevant stakeholders, as well as financial intermediaries and service providers with the right information and incentives to perform their roles and help to ensure accountability within a framework of checks and balances.', 'OECD', 'climate', 'in_force', '2023-01-01'::date, 'OECD', 'https://www.oecd.org/content/dam/oecd/en/publications/reports/2023/09/g20-oecd-principles-of-corporate-governance-2023_60836fcb/ed750b30-en.pdf', ARRAY['guidance_frameworks', 'oecd', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('25d243d6-7c81-5f19-bf23-320ec2a74431', 'OECD Due Diligence for Responsible Corporate Lending and Securities', 'Due Diligence for Responsible Corporate Lending and Securities Underwriting, 2019', 'Due Diligence for Responsible Corporate Lending and Securities Underwriting, provides a common global framework for financial institutions to carry out due diligence to identify, respond to, and publicly communicate on environmental and social risks associated with their clients.', 'Due Diligence for Responsible Corporate Lending and Securities Underwriting, provides a common global framework for financial institutions to carry out due diligence to identify, respond to, and publicly communicate on environmental and social risks associated with their clients.', 'Due Diligence for Responsible Corporate Lending and Securities Underwriting, provides a common global framework for financial institutions to carry out due diligence to identify, respond to, and publicly communicate on environmental and social risks associated with their clients.', 'OECD', 'governance', 'in_force', '2019-01-01'::date, 'Organisation for Economic Co-operation and Development (OECD)', 'https://www.carrotsandsticks.org/policies/319_4', ARRAY['voluntary_frameworks', 'voluntary', 'oecd', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fe119e2f-8b46-5b04-8558-43e81ea7b0ed', 'OECD Due Diligence Guidance for Responsible Business Conduct', 'OECD Due Diligence Guidance for Responsible Business Conduct, 2018', 'The OECD Due Diligence Guidance for Responsible Business Conduct provides practical support to enterprises on the implementation of the OECD Guidelines for Multinational Enterprises by providing plain-language explanations of its due diligence recommendations and associated provisions. Implementing these recommendations can help enterprises avoid and address adverse impacts related to workers, human rights, the environment, bribery, consumers and corporate governance that may be associated with their operations, supply chains and other business relationships. The Guidance includes additional explanations, tips and illustrative examples of due diligence.', 'The OECD Due Diligence Guidance for Responsible Business Conduct provides practical support to enterprises on the implementation of the OECD Guidelines for Multinational Enterprises by providing plain-language explanations of its due diligence recommendations and associated provisions. Implementing these recommendations can help enterprises avoid and address adverse impacts related to workers, human rights, the environment, bribery, consumers and corporate governance that may be associated with their operations, supply chains and other business relationships. The Guidance includes additional explanations, tips and illustrative examples of due diligence.', 'The OECD Due Diligence Guidance for Responsible Business Conduct provides practical support to enterprises on the implementation of the OECD Guidelines for Multinational Enterprises by providing plain-language explanations of its due diligence recommendations and associated provisions. Implementing these recommendations can help enterprises avoid and address adverse impacts related to workers, human rights, the environment, bribery, consumers and corporate governance that may be associated with their operations, supply chains and other business relationships. The Guidance includes additional explanations, tips and illustrative examples of due diligence.', 'OECD', 'climate', 'in_force', '2018-01-01'::date, 'OECD', 'https://www.oecd.org/content/dam/oecd/en/publications/reports/2018/02/oecd-due-diligence-guidance-for-responsible-business-conduct_c669bd57/15f5f4b3-en.pdf', ARRAY['guidance_frameworks', 'sdg8', 'oecd', 'sdg16', 'sdg12', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7028bc11-62d2-58f8-a2eb-10c3bf4bb442', 'OECD Due Diligence Guidance for Responsible Supply Chains', 'OECD Due Diligence Guidance for Responsible Supply Chains in the Garment and Footwear Sector, 2018', 'The OECD Due Diligence Guidance for Responsible Supply Chains in the Garment and Footwear Sector helps enterprises implement the due diligence recommendations contained in the OECD Guidelines for Multinational Enterprises along the garment and footwear supply chain in order to avoid and address the potential negative impacts of their activities and supply chains.', 'The OECD Due Diligence Guidance for Responsible Supply Chains in the Garment and Footwear Sector helps enterprises implement the due diligence recommendations contained in the OECD Guidelines for Multinational Enterprises along the garment and footwear supply chain in order to avoid and address the potential negative impacts of their activities and supply chains.', 'The OECD Due Diligence Guidance for Responsible Supply Chains in the Garment and Footwear Sector helps enterprises implement the due diligence recommendations contained in the OECD Guidelines for Multinational Enterprises along the garment and footwear supply chain in order to avoid and address the potential negative impacts of their activities and supply chains.', 'OECD', 'circularity', 'in_force', '2018-01-01'::date, 'OECD', 'https://www.oecd.org/content/dam/oecd/en/publications/reports/2018/03/oecd-due-diligence-guidance-for-responsible-supply-chains-in-the-garment-and-footwear-sector_g1g89b0b/9789264290587-en.pdf', ARRAY['guidance_frameworks', 'oecd', 'sdg12', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d87b7a5a-1f6a-5d9b-91a3-18fa34f1ca8f', 'OECD Due Diligence Guidance for Meaningful Stakeholder Engagement', 'OECD Due Diligence Guidance for Meaningful Stakeholder Engagement in the Extractive Sector, 2017', 'The OECD has prepared a Due Diligence Guidance for Meaningful Stakeholder Engagement in the Extractive Sector intended to provide practical guidance to mining, oil and gas enterprises in addressing the challenges related to stakeholder engagement. This guide is part of the work the OECD undertakes to create practical sectoral applications for the recommendations found in the OECD Guidelines for Multinational Enterprises.', 'The OECD has prepared a Due Diligence Guidance for Meaningful Stakeholder Engagement in the Extractive Sector intended to provide practical guidance to mining, oil and gas enterprises in addressing the challenges related to stakeholder engagement. This guide is part of the work the OECD undertakes to create practical sectoral applications for the recommendations found in the OECD Guidelines for Multinational Enterprises.', 'The OECD has prepared a Due Diligence Guidance for Meaningful Stakeholder Engagement in the Extractive Sector intended to provide practical guidance to mining, oil and gas enterprises in addressing the challenges related to stakeholder engagement. This guide is part of the work the OECD undertakes to create practical sectoral applications for the recommendations found in the OECD Guidelines for Multinational Enterprises.', 'OECD', 'climate', 'in_force', '2017-01-01'::date, 'OECD', 'https://legalinstruments.oecd.org/public/doc/341/341.en.pdf', ARRAY['oecd', 'regulations', 'sdg17', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ae799a65-65ec-55d7-92f2-148d95738c4a', 'OECD Due Diligence Guidance for Responsible supply Chains', 'OECD Due Diligence Guidance for Responsible supply Chains of Minerals from Conflict-Affected and High-Risk Areas, 2016', 'The OECD Due Diligence Guidance provides detailed recommendations to help companies respect human rights and avoid contributing to conflict through their mineral purchasing decisions and practices. This Guidance is for use by any company potentially sourcing minerals or metals from conflict-affected and high-risk areas. The OECD Guidance is global in scope and applies to all mineral supply chains.', 'The OECD Due Diligence Guidance provides detailed recommendations to help companies respect human rights and avoid contributing to conflict through their mineral purchasing decisions and practices. This Guidance is for use by any company potentially sourcing minerals or metals from conflict-affected and high-risk areas. The OECD Guidance is global in scope and applies to all mineral supply chains.', 'The OECD Due Diligence Guidance provides detailed recommendations to help companies respect human rights and avoid contributing to conflict through their mineral purchasing decisions and practices. This Guidance is for use by any company potentially sourcing minerals or metals from conflict-affected and high-risk areas. The OECD Guidance is global in scope and applies to all mineral supply chains.', 'OECD', 'climate', 'in_force', '2016-01-01'::date, 'Organisation for Economic Co-operation and Development (OECD)', 'https://www.carrotsandsticks.org/policies/319_10', ARRAY['guidance_frameworks', 'oecd', 'sdg16', 'sdg12', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('96eaf3b1-254a-5da5-9fdf-925981a73557', 'G20/OECD Principles of Corporate Governance', 'G20/OECD Principles of Corporate Governance, 2015', 'The G20/OECD Principles of Corporate Governance help policy makers evaluate and improve the legal, regulatory, and institutional framework for corporate governance. They also provide guidance for stock exchanges, investors, corporations, and others that have a role in the process of developing good corporate governance. First issued in 1999, the Principles have become the international benchmark in corporate governance. They have been adopted as one of the Financial Stability Board’s Key Standards for Sound Financial Systems and endorsed by the G20.', 'The G20/OECD Principles of Corporate Governance help policy makers evaluate and improve the legal, regulatory, and institutional framework for corporate governance. They also provide guidance for stock exchanges, investors, corporations, and others that have a role in the process of developing good corporate governance. First issued in 1999, the Principles have become the international benchmark in corporate governance. They have been adopted as one of the Financial Stability Board’s Key Standards for Sound Financial Systems and endorsed by the G20.', 'The G20/OECD Principles of Corporate Governance help policy makers evaluate and improve the legal, regulatory, and institutional framework for corporate governance. They also provide guidance for stock exchanges, investors, corporations, and others that have a role in the process of developing good corporate governance. First issued in 1999, the Principles have become the international benchmark in corporate governance. They have been adopted as one of the Financial Stability Board’s Key Standards for Sound Financial Systems and endorsed by the G20.', 'OECD', 'governance', 'in_force', '2015-01-01'::date, 'OECD', 'https://www.oecd.org/content/dam/oecd/en/publications/reports/2015/11/g20-oecd-principles-of-corporate-governance_g1g56c3d/9789264236882-en.pdf', ARRAY['guidance_frameworks', 'oecd', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6ac90227-271d-5759-8c81-80b4600d560c', 'OECD Guidelines on Corporate Governance of State-owned Enterprises', 'OECD Guidelines on Corporate Governance of State-owned Enterprises - Draft for Public Comment, 2014', 'These Guidelines are intended to provide general advice that will assist governments in improving the performance of SOEs so the decision to apply the Guidelines to the governance of particular SOEs should be made on a pragmatic basis.', 'These Guidelines are intended to provide general advice that will assist governments in improving the performance of SOEs so the decision to apply the Guidelines to the governance of particular SOEs should be made on a pragmatic basis.', 'These Guidelines are intended to provide general advice that will assist governments in improving the performance of SOEs so the decision to apply the Guidelines to the governance of particular SOEs should be made on a pragmatic basis.', 'OECD', 'governance', 'in_force', '2014-01-01'::date, 'OECD', 'https://www.ecgi.global/sites/default/files/codes/documents/oecd_soe_guidelines_may2014_en.pdf', ARRAY['guidance_frameworks', 'oecd', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d01d96d3-630d-5575-914d-fcd872f16385', 'OECD Guidelines for Multinational Enterprises', 'OECD Guidelines for Multinational Enterprises, 2011', 'The OECD Guidelines for Multinational Enterprises are far reaching recommendations for responsible business conduct that 44 adhering governments – representing all regions of the world and accounting for 85% of foreign direct investment – encourage their enterprises to observe wherever they operate. The Guidelines were updated in 2011 for the fifth time since they were first adopted in 1976. This booklet contains the official version of the text, implementation procedures and commentary of the 2011 update.', 'The OECD Guidelines for Multinational Enterprises are far reaching recommendations for responsible business conduct that 44 adhering governments – representing all regions of the world and accounting for 85% of foreign direct investment – encourage their enterprises to observe wherever they operate. The Guidelines were updated in 2011 for the fifth time since they were first adopted in 1976. This booklet contains the official version of the text, implementation procedures and commentary of the 2011 update.', 'The OECD Guidelines for Multinational Enterprises are far reaching recommendations for responsible business conduct that 44 adhering governments – representing all regions of the world and accounting for 85% of foreign direct investment – encourage their enterprises to observe wherever they operate. The Guidelines were updated in 2011 for the fifth time since they were first adopted in 1976. This booklet contains the official version of the text, implementation procedures and commentary of the 2011 update.', 'OECD', 'governance', 'in_force', '2011-01-01'::date, 'OECD', 'https://www.oecd.org/en/publications/2011/09/oecd-guidelines-for-multinational-enterprises-2011-edition_g1g13daf.html', ARRAY['guidance_frameworks', 'voluntary', 'oecd', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f9359b62-428c-5d93-9d97-539072416355', 'OECD Guidelines on Corporate Governance of State-owned Enterprises', 'OECD Guidelines on Corporate Governance of State-owned Enterprises, 2005', 'The OECD Guidelines on Corporate Governance of State-Owned Enterprises give concrete advice to countries on how to manage more effectively their responsibilities as company owners, thus helping to make state-owned enterprises more competitive, efficient and transparent.', 'The OECD Guidelines on Corporate Governance of State-Owned Enterprises give concrete advice to countries on how to manage more effectively their responsibilities as company owners, thus helping to make state-owned enterprises more competitive, efficient and transparent.', 'The OECD Guidelines on Corporate Governance of State-Owned Enterprises give concrete advice to countries on how to manage more effectively their responsibilities as company owners, thus helping to make state-owned enterprises more competitive, efficient and transparent.', 'OECD', 'governance', 'in_force', '2005-01-01'::date, 'OECD', 'https://publicgovernance.de/media/CG_OECD_Guidelines_2005.pdf', ARRAY['guidance_frameworks', 'oecd', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cd21b776-bcfa-5479-b283-e2b050b927a6', 'OECD Corporate Governance of State-owned Enterprises', 'Guidelines on Corporate Governance of State-owned Enterprises, 2004', 'These Guidelines should be seen as complementary to the OECD Principles of Corporate Governance and oriented to the range of specific governance issues related to SOEs. They accordingly adopt the perspective of the state as an owner, focusing on the characteristics and components of its policy which would ensure good corporate governance. In addition to this, these Guidelines deal with the way in which the ownership function should be organised within the state administration, how boards should be appointed and vested with responsibilities and how transparency should be ensured. It should be understood that these Guidelines only seek to amplify or add specificity to the OECD Principles of Corporate Governance in certain areas, and do not supersede nor conflict with them.', 'These Guidelines should be seen as complementary to the OECD Principles of Corporate Governance and oriented to the range of specific governance issues related to SOEs. They accordingly adopt the perspective of the state as an owner, focusing on the characteristics and components of its policy which would ensure good corporate governance. In addition to this, these Guidelines deal with the way in which the ownership function should be organised within the state administration, how boards should be appointed and vested with responsibilities and how transparency should be ensured. It should be understood that these Guidelines only seek to amplify or add specificity to the OECD Principles of Corporate Governance in certain areas, and do not supersede nor conflict with them.', 'These Guidelines should be seen as complementary to the OECD Principles of Corporate Governance and oriented to the range of specific governance issues related to SOEs. They accordingly adopt the perspective of the state as an owner, focusing on the characteristics and components of its policy which would ensure good corporate governance. In addition to this, these Guidelines deal with the way in which the ownership function should be organised within the state administration, how boards should be appointed and vested with responsibilities and how transparency should be ensured. It should be understood that these Guidelines only seek to amplify or add specificity to the OECD Principles of Corporate Governance in certain areas, and do not supersede nor conflict with them.', 'OECD', 'governance', 'in_force', '2004-01-01'::date, 'OECD', 'https://www.ecgi.global/sites/default/files/codes/documents/oecd_guidelines_dec2004.pdf', ARRAY['guidance_frameworks', 'oecd', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1b7ac76b-62fa-54bb-bec4-a9bcaedfe441', 'Corporate Governance Code based on OECD Principles', 'Corporate Governance Code based on OECD Principles, 2004', 'This Corporate Governance Code based on the OECD Principles (2004) (hereinafter the “2004 Code”) was prepared in the light of the need to update the original Corporate Governance Code based on the OECD Principles of 2001 (hereinafter the “2001 Code”) drawn up by the Securities Commission (hereinafter “SEC”) in cooperation with experts of the British Know How Fund.', 'This Corporate Governance Code based on the OECD Principles (2004) (hereinafter the “2004 Code”) was prepared in the light of the need to update the original Corporate Governance Code based on the OECD Principles of 2001 (hereinafter the “2001 Code”) drawn up by the Securities Commission (hereinafter “SEC”) in cooperation with experts of the British Know How Fund.', 'This Corporate Governance Code based on the OECD Principles (2004) (hereinafter the “2004 Code”) was prepared in the light of the need to update the original Corporate Governance Code based on the OECD Principles of 2001 (hereinafter the “2001 Code”) drawn up by the Securities Commission (hereinafter “SEC”) in cooperation with experts of the British Know How Fund.', 'OECD', 'governance', 'in_force', '2004-01-01'::date, 'OECD', 'https://www.oecd.org/content/dam/oecd/en/publications/reports/2004/05/oecd-principles-of-corporate-governance-2004_g1gh44a5/9789264015999-en.pdf', ARRAY['guidance_frameworks', 'oecd', 'sdg17', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6d848bb9-1187-560c-92d8-20bcff26c2bf', 'OECD Guidelines for Multinational Enterprises', 'OECD Guidelines for Multinational Enterprises, 1997', 'The OECD Guidelines for Multinational Enterprises are an essential component of the 1976 Declaration on International Investment and Multinational Enterprises. The Guidelines are recommendations jointly addressed by the OECD governments to multinational enterprises operating in their territories. Setting voluntary standards of behaviour, they provide guidance to multinational enterprises and help to ensure that their operations are in harmony with the policies of the countries in which they operate.', 'The OECD Guidelines for Multinational Enterprises are an essential component of the 1976 Declaration on International Investment and Multinational Enterprises. The Guidelines are recommendations jointly addressed by the OECD governments to multinational enterprises operating in their territories. Setting voluntary standards of behaviour, they provide guidance to multinational enterprises and help to ensure that their operations are in harmony with the policies of the countries in which they operate.', 'The OECD Guidelines for Multinational Enterprises are an essential component of the 1976 Declaration on International Investment and Multinational Enterprises. The Guidelines are recommendations jointly addressed by the OECD governments to multinational enterprises operating in their territories. Setting voluntary standards of behaviour, they provide guidance to multinational enterprises and help to ensure that their operations are in harmony with the policies of the countries in which they operate.', 'OECD', 'governance', 'in_force', '1997-01-01'::date, 'Organisation for Economic Co-operation and Development (OECD)', 'https://www.carrotsandsticks.org/policies/319_1', ARRAY['guidance_frameworks', 'voluntary', 'oecd', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('75ff6ff8-978b-5359-9705-89b72b78e1a2', 'Pakistan PSX Primer on Environmental, Social and Governance (ESG)', 'PSX Primer on Environmental, Social and Governance (ESG) Reporting Guidance for Companies', 'The PSX Primer provides ESG reporting guidance for companies in Pakistan, emphasizing stakeholder engagement, risk management, and access to capital. It outlines the importance of ESG integration, benefits of reporting, and stages of drafting an ESG report, targeting companies seeking to enhance sustainability practices and transparency.', 'The PSX Primer provides ESG reporting guidance for companies in Pakistan, emphasizing stakeholder engagement, risk management, and access to capital. It outlines the importance of ESG integration, benefits of reporting, and stages of drafting an ESG report, targeting companies seeking to enhance sustainability practices and transparency.', 'The PSX Primer provides ESG reporting guidance for companies in Pakistan, emphasizing stakeholder engagement, risk management, and access to capital. It outlines the importance of ESG integration, benefits of reporting, and stages of drafting an ESG report, targeting companies seeking to enhance sustainability practices and transparency.', 'Pakistan', 'climate', 'in_force', '2024-01-01'::date, 'Pakistan', 'https://www.carrotsandsticks.org/policies/138_13', ARRAY['guidance_frameworks', 'sdg17', 'mandatory', 'pakistan', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('63502359-1471-5859-8c3a-bc388c029f3d', 'Rule Book of Pakistan Stock Exchange Limited (PSX)', 'Rule Book of Pakistan Stock Exchange Limited (PSX), 2021', 'This Rule Book is divided into 24 dedicated chapters, which has turned out to be a handy regulatory document for the regulated entities of PSX and stock market investors in terms of understanding the requirements, rights and obligations as well as recourse available to investors in case of dispute.', 'This Rule Book is divided into 24 dedicated chapters, which has turned out to be a handy regulatory document for the regulated entities of PSX and stock market investors in terms of understanding the requirements, rights and obligations as well as recourse available to investors in case of dispute.', 'This Rule Book is divided into 24 dedicated chapters, which has turned out to be a handy regulatory document for the regulated entities of PSX and stock market investors in terms of understanding the requirements, rights and obligations as well as recourse available to investors in case of dispute.', 'Pakistan', 'governance', 'in_force', '2021-01-01'::date, 'Pakistan', 'https://www.carrotsandsticks.org/policies/138_11', ARRAY['pakistan', 'mandatory', 'other sustainability policy', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('42319b3a-819a-5165-ac52-6195f22c27c1', 'Pakistan National Action Plan on Business and Human Rights', 'National Action Plan on Business and Human Rights', 'The 2021 Pakistan National Action Plan on Business and Human Rights is a policy framework aimed at promoting respect for human rights by businesses operating in Pakistan. The plan is based on the UN Guiding Principles on Business and Human Rights and sets out a number of measures to be taken by the government, businesses, and other stakeholders to ensure that businesses respect human rights in their operations. The plan focuses on a range of human rights issues, including labor rights, environmental protection, and the rights of women, children, and marginalized groups. It emphasizes the importance of due diligence by businesses to identify and address human rights risks, and the need for access to effective remedies for those affected by human rights violations. The plan also includes measures to strengthen the legal and regulatory framework for business and human rights in Pakistan, including the development of a national human rights policy and the establishment of a national human rights commission.', 'The 2021 Pakistan National Action Plan on Business and Human Rights is a policy framework aimed at promoting respect for human rights by businesses operating in Pakistan. The plan is based on the UN Guiding Principles on Business and Human Rights and sets out a number of measures to be taken by the government, businesses, and other stakeholders to ensure that businesses respect human rights in their operations. The plan focuses on a range of human rights issues, including labor rights, environmental protection, and the rights of women, children, and marginalized groups. It emphasizes the importance of due diligence by businesses to identify and address human rights risks, and the need for access to effective remedies for those affected by human rights violations. The plan also includes measures to strengthen the legal and regulatory framework for business and human rights in Pakistan, including the development of a national human rights policy and the establishment of a national human rights commission.', 'The 2021 Pakistan National Action Plan on Business and Human Rights is a policy framework aimed at promoting respect for human rights by businesses operating in Pakistan. The plan is based on the UN Guiding Principles on Business and Human Rights and sets out a number of measures to be taken by the government, businesses, and other stakeholders to ensure that businesses respect human rights in their operations. The plan focuses on a range of human rights issues, including labor rights, environmental protection, and the rights of women, children, and marginalized groups. It emphasizes the importance of due diligence by businesses to identify and address human rights risks, and the need for access to effective remedies for those affected by human rights violations. The plan also includes measures to strengthen the legal and regulatory framework for business and human rights in Pakistan, including the development of a national human rights policy and the establishment of a national human rights commission.', 'Pakistan', 'climate', 'in_force', '2021-01-01'::date, 'Pakistan', 'https://www.carrotsandsticks.org/policies/138_12', ARRAY['sdg8', 'sdg10', 'regulations', 'mandatory', 'sdg5', 'pakistan', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
