INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('567ab4e6-d754-5b2f-997a-384e062413d9', 'Pakistan Corporate Social Responsibility Voluntary Guidelines', 'Corporate Social Responsibility Voluntary Guidelines, 2013', 'The objective of these Guidelines is to promote the development of a framework for CSR initiatives by all companies. Companies are encouraged to strive and work in cooperation with stakeholders for implementing a transparent and socially responsible strategy.', 'The objective of these Guidelines is to promote the development of a framework for CSR initiatives by all companies. Companies are encouraged to strive and work in cooperation with stakeholders for implementing a transparent and socially responsible strategy.', 'The objective of these Guidelines is to promote the development of a framework for CSR initiatives by all companies. Companies are encouraged to strive and work in cooperation with stakeholders for implementing a transparent and socially responsible strategy.', 'Pakistan', 'governance', 'in_force', '2013-01-01'::date, 'Pakistan', 'https://www.carrotsandsticks.org/policies/138_4', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg17', 'pakistan', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('aaeab945-8bdf-54c1-a364-f1fc72b77e32', 'Pakistan Corporate Social Responsibility Voluntary Guidelines', 'Corporate Social Responsibility Voluntary Guidelines, 2012', 'These Voluntary Guidelines for Corporate Social Responsibility (“the Guidelines”) are being introduced by SECP primarily aimed at encouraging responsible business activities that support community growth for public interest and eliminate practices that harm the public sphere.', 'These Voluntary Guidelines for Corporate Social Responsibility (“the Guidelines”) are being introduced by SECP primarily aimed at encouraging responsible business activities that support community growth for public interest and eliminate practices that harm the public sphere.', 'These Voluntary Guidelines for Corporate Social Responsibility (“the Guidelines”) are being introduced by SECP primarily aimed at encouraging responsible business activities that support community growth for public interest and eliminate practices that harm the public sphere.', 'Pakistan', 'climate', 'in_force', '2012-01-01'::date, 'Pakistan', 'https://www.carrotsandsticks.org/policies/138_2', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg11', 'pakistan', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f9330c16-0e4b-5133-ac73-c7ecbdcc18f3', 'Pakistan Code of Corporate Governance', 'Code of Corporate Governance, 2012', 'The revisions in the Code are indicative of the fact that governance standards are dynamic and need to be reviewed to keep the governance framework relevant and effective. Therefore, in order to keep pace with the constantly evolving corporate sector and financial markets and the resultant governance benchmarks, the process of revising the Code was initiated. The objective was to further improve and raise the standards of corporate governance in the country while at the same time taking into consideration the global developments in corporate governance.', 'The revisions in the Code are indicative of the fact that governance standards are dynamic and need to be reviewed to keep the governance framework relevant and effective. Therefore, in order to keep pace with the constantly evolving corporate sector and financial markets and the resultant governance benchmarks, the process of revising the Code was initiated. The objective was to further improve and raise the standards of corporate governance in the country while at the same time taking into consideration the global developments in corporate governance.', 'The revisions in the Code are indicative of the fact that governance standards are dynamic and need to be reviewed to keep the governance framework relevant and effective. Therefore, in order to keep pace with the constantly evolving corporate sector and financial markets and the resultant governance benchmarks, the process of revising the Code was initiated. The objective was to further improve and raise the standards of corporate governance in the country while at the same time taking into consideration the global developments in corporate governance.', 'Pakistan', 'governance', 'in_force', '2012-01-01'::date, 'Pakistan', 'https://www.carrotsandsticks.org/policies/138_8', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'pakistan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1a665619-e115-5c1e-8a71-51ee2fbc46f9', 'Pakistan Statutory Notifications (S.R.O)', 'Statutory Notifications (S.R.O)', 'This document is concerned with the Companies (Corporate Social Responsibility) General Order, 2009. It shall be applicable on all the public companies from the financial year beginning on or after July 1, 2009.', 'This document is concerned with the Companies (Corporate Social Responsibility) General Order, 2009. It shall be applicable on all the public companies from the financial year beginning on or after July 1, 2009.', 'This document is concerned with the Companies (Corporate Social Responsibility) General Order, 2009. It shall be applicable on all the public companies from the financial year beginning on or after July 1, 2009.', 'Pakistan', 'governance', 'in_force', '2009-01-01'::date, 'Pakistan', 'https://www.carrotsandsticks.org/policies/138_3', ARRAY['pakistan', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5875d3c6-59b9-550e-b124-3ff8da0f892c', 'Protocol. Responsible Business Conduct. Panama: Insurance Sector', 'Protocol. Responsible Business Conduct. Panama: Insurance Sector', 'The Sectoral Protocol for Responsible Business Conduct in the Insurance Sector in Panama aims to raise sustainability standards in the sector. In relation to the concept of responsible business conduct introduced in number 1, it is based on different guidelines and recommendations at the international level: OECD Guidelines for Multinational Companies; ILO''s Tripartite Declaration of Principles on Multinational Companies and Social Policy; World Bank''s Good Practices for Financial Consumer Protection.', 'The Sectoral Protocol for Responsible Business Conduct in the Insurance Sector in Panama aims to raise sustainability standards in the sector. In relation to the concept of responsible business conduct introduced in number 1, it is based on different guidelines and recommendations at the international level: OECD Guidelines for Multinational Companies; ILO''s Tripartite Declaration of Principles on Multinational Companies and Social Policy; World Bank''s Good Practices for Financial Consumer Protection.', 'The Sectoral Protocol for Responsible Business Conduct in the Insurance Sector in Panama aims to raise sustainability standards in the sector. In relation to the concept of responsible business conduct introduced in number 1, it is based on different guidelines and recommendations at the international level: OECD Guidelines for Multinational Companies; ILO''s Tripartite Declaration of Principles on Multinational Companies and Social Policy; World Bank''s Good Practices for Financial Consumer Protection.', 'Panama', 'climate', 'in_force', '2022-01-01'::date, 'Panama', 'https://www.carrotsandsticks.org/policies/140_3', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'panama']::text[]) ON CONFLICT (id) DO NOTHING;
